<div id="kt_content_container" class="container-xxl py-5">
    <div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Mis Pedidos y Compras Realizadas</h1><div class="text-muted fs-6">Consulta el historial de tus pedidos</div></div></div>
    <div id="alerta-pedidos"></div>
    <div class="card card-flush"><div class="card-body pt-0"><div class="table-responsive"><table class="table align-middle table-row-dashed fs-6 gy-5" id="tabla_pedidos"><thead><tr class="text-start text-gray-500 fw-bold fs-7 text-uppercase gs-0"><th>Pedido</th><th>Fecha</th><th>Total</th><th>Estatus</th><th>Acciones</th></tr></thead><tbody></tbody></table></div></div></div>
</div>
<div class="modal fade" id="modal_detalle_pedido" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content"><div class="modal-header"><h2 class="fw-bold">Detalle del Pedido</h2><button type="button" class="btn btn-icon btn-sm btn-active-light-primary" data-bs-dismiss="modal"><i class="ki-outline ki-cross fs-1"></i></button></div><div class="modal-body" id="contenido_detalle_pedido"></div></div></div></div>
<script>
(function () {
    const tabla = $('#tabla_pedidos'), alerta = document.getElementById('alerta-pedidos');
    function estatusPedido(estatus) { const estados = { 1: ['Pendiente', 'warning'], 2: ['Procesando', 'primary'], 3: ['Entregado', 'success'], 4: ['Cancelado', 'danger'] }; const estado = estados[estatus] || ['Desconocido', 'secondary']; return '<span class="badge badge-light-' + estado[1] + '">' + estado[0] + '</span>'; }
    fetch('actions/16.read_pedidos.php').then(r => r.json()).then(respuesta => {
        if (!respuesta.success) { alerta.innerHTML = '<div class="alert alert-danger">' + (respuesta.error || 'No se pudieron cargar los pedidos.') + '</div>'; return; }
        const filas = (respuesta.data || []).map(pedido => [ '<span class="fw-bold text-gray-800">#' + pedido.id_pedido + '</span>', pedido.fecha_pedido, '$' + Number(pedido.total).toFixed(2) + ' MXN', estatusPedido(pedido.estatus), '<button type="button" class="btn btn-sm btn-light-primary ver-pedido" data-id-pedido="' + pedido.id_pedido + '">Ver detalle</button>' + (Number(pedido.estatus) === 1 ? ' <button type="button" class="btn btn-sm btn-light-danger cambiar-estatus" data-estatus="4" data-id-pedido="' + pedido.id_pedido + '">Cancelar</button>' : '') ]);
        tabla.DataTable({ data: filas, columns: [{ title: 'Pedido' }, { title: 'Fecha' }, { title: 'Total' }, { title: 'Estatus' }, { title: 'Acciones' }], pageLength: 10, order: [[1, 'desc']], language: { url: 'https://cdn.datatables.net/plug-ins/1.13.7/i18n/es-ES.json' }, columnDefs: [{ targets: [3, 4], orderable: false }] });
    }).catch(() => alerta.innerHTML = '<div class="alert alert-danger">Ocurrió un error de conexión.</div>');
    tabla.on('click', '.cambiar-estatus', function () { const boton = $(this), datos = new FormData(); datos.append('id_pedido', boton.data('id-pedido')); datos.append('estatus', boton.data('estatus')); fetch('actions/17.update_estatus_pedido.php', { method: 'POST', body: datos }).then(r => r.json()).then(respuesta => { alerta.innerHTML = '<div class="alert alert-' + (respuesta.success ? 'success' : 'danger') + '">' + (respuesta.message || respuesta.error) + '</div>'; if (respuesta.success) setTimeout(() => $('#principal').load('system/06.mis_pedidos.php'), 700); }); });
    tabla.on('click', '.ver-pedido', function () { fetch('actions/16.read_pedidos.php?id_pedido=' + $(this).data('id-pedido')).then(r => r.json()).then(respuesta => { if (!respuesta.success) return; const pedido = respuesta.data; document.getElementById('contenido_detalle_pedido').innerHTML = '<p><strong>Pedido:</strong> #' + pedido.id_pedido + '</p><p><strong>Fecha:</strong> ' + pedido.fecha_pedido + '</p><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th></tr></thead><tbody>' + pedido.productos.map(item => '<tr><td>' + item.producto_nombre + '</td><td>' + item.cantidad + '</td><td>$' + Number(item.precio_unitario).toFixed(2) + '</td></tr>').join('') + '</tbody></table></div><div class="text-end fw-bold fs-4">Total: $' + Number(pedido.total).toFixed(2) + ' MXN</div>'; bootstrap.Modal.getOrCreateInstance(document.getElementById('modal_detalle_pedido')).show(); }); });
})();
</script>
